const loadEv = () => { try { return JSON.parse(store.get('fredi-events') || '[]'); } catch(e){ return []; } };
function logEv(ev, detail = '', ms = ''){
  if (S.quiet) return;
  const l = loadEv(); l.push({ t:new Date().toISOString(), code:S.profile?.code || '', option:`Card ${S.onb}, context ${S.ctx}`, device: app.clientWidth <= 760 ? 'Phone' : 'Laptop', ev, run:RUN, detail:String(detail), seconds: ms === '' ? '' : Math.round(ms/1000) });
  if (l.length > 3000) l.splice(0, l.length - 3000);
  store.set('fredi-events', JSON.stringify(l)); if (typeof renderEvLog === 'function') renderEvLog();
}
