function parseHash(){
  const h = location.hash.replace('#','');
  const m = h.match(/^(test-)?([AB])([AB])$/);
  if (m){ S.test = !!m[1]; S.onb = m[2]; S.ctx = m[3]; }
  else if (h === 'test'){ S.test = true; }
  if (STUDENT) S.test = true;
}
/* Student file: each session starts with a random design variant, unless the link sets one (#AA, #test-AB, …) */
function assignStart(){
  const fixed = /[AB][AB]$/.test(location.hash);
  if (STUDENT && !fixed){ S.onb = Math.random() < .5 ? 'A' : 'B'; S.ctx = Math.random() < .5 ? 'A' : 'B'; }
  S.assigned = { scenarioCard:S.onb, scenarioContext:S.ctx, random:STUDENT && !fixed };
}
try { const v = JSON.parse(store.get('fredi-review') || '{}'); ['onb','ctx','frame','theme'].forEach(k => v[k] && (S[k] = v[k])); if (v.logo in MARKS) S.logo = +v.logo; S.showAgents = !!v.showAgents; if (Array.isArray(v.short)) S.short = v.short.filter(n => n in MARKS); } catch(e){}
parseHash(); assignStart();
const saveReview = () => store.set('fredi-review', JSON.stringify({onb:S.onb,ctx:S.ctx,frame:S.frame,theme:S.theme,logo:S.logo,short:S.short,showAgents:S.showAgents}));

/* ---------- Formatting ---------- */
const inline = s => esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');
function fmt(t){
  return t.split(/\n\n/).map(block => {
    const lines = block.split('\n');
    if (lines.every(l => /^- /.test(l))) return '<ul>' + lines.map(l => `<li>${inline(l.slice(2))}</li>`).join('') + '</ul>';
    if (lines.every(l => /^\d+\. /.test(l))) return '<ol>' + lines.map(l => `<li>${inline(l.replace(/^\d+\. /,''))}</li>`).join('') + '</ol>';
    return `<p>${lines.map(inline).join('<br>')}</p>`;
  }).join('');
}

