  if (S.ctx==='A' && S.tab==='ctx') return 'Company profile tab';
  if (S.cardStatus !== 'confirmed') return (S.cardStatus === 'reviewing' ? 'Company profile review, ' : 'Company profile setup, ') + where;
  if (!S.messages.length) return 'Empty new chat';
