let fbShot = null, fbShotSeq = 0;
function setShot(url){ fbShot = url; $('#fbShotPrev').innerHTML = url ? `<img src="${url}" alt="Screenshot that will be sent with your feedback">` : '<span class="help">No screenshot</span>'; }
async function captureApp(maxW = 1280, q = .72){
  if (typeof html2canvas !== 'function') return null;
  const bg = getComputedStyle(document.body).backgroundColor;
  const scale = Math.min(1, maxW / Math.max(app.clientWidth, 1));
  /* html2canvas draws scrolled areas from the top, so the scroll positions are copied into its clone */
  const scrolled = [...app.querySelectorAll('*')].filter(el => el.scrollTop > 0);
  scrolled.forEach((el, i) => el.setAttribute('data-h2c', i));
  const c = await html2canvas(app, { backgroundColor:bg, scale, logging:false, useCORS:true,
    onclone: doc => scrolled.forEach((el, i) => { const k = doc.querySelector(`[data-h2c="${i}"]`); if (k){ k.style.overflow = 'hidden'; [...k.children].forEach(ch => { ch.style.transform = `translateY(${-el.scrollTop}px)`; }); } }) });
  scrolled.forEach(el => el.removeAttribute('data-h2c'));
  return c.toDataURL('image/jpeg', q);
}
