const FONTS = {
  'Plus Jakarta Sans':'Plus+Jakarta+Sans:wght@400;500;600;700;800',
  'Inter':'Inter:wght@400;500;600;700;800',
  'DM Sans':'DM+Sans:wght@400;500;600;700;800',
  'Source Sans 3':'Source+Sans+3:wght@400;500;600;700;800',
  'Lexend':'Lexend:wght@400;500;600;700;800',
  'IBM Plex Sans':'IBM+Plex+Sans:wght@400;500;600;700',
  'Nunito Sans':'Nunito+Sans:wght@400;500;600;700;800',
  'Figtree':'Figtree:wght@400;500;600;700;800'
};
const DEF = { font:'Plus Jakarta Sans', size:'m', corners:'soft', contrast:'normal', colors:{}, expert:false, side:'right', panelW:368, chatW:56, density:'normal', showTime:true, showThws:true, showHint:false };
const COLOR_DEF = { brand:'#FF6A00', paper:'#F4F4F3', surface:'#FFFFFF', ink:'#1A1A1A' };
let D; try { D = Object.assign(structuredClone(DEF), JSON.parse(store.get('fredi-design') || '{}')); } catch(e){ D = structuredClone(DEF); }
const saveD = () => store.set('fredi-design', JSON.stringify(D));
const loaded = new Set(['Plus Jakarta Sans']);
function loadFont(name){
  if (loaded.has(name) || !FONTS[name]) return; loaded.add(name);
  const l = document.createElement('link'); l.rel = 'stylesheet'; l.href = `https://fonts.googleapis.com/css2?family=${FONTS[name]}&display=swap`; document.head.appendChild(l);
}
const hex2rgb = h => { const n = parseInt(h.slice(1),16); return [n>>16&255, n>>8&255, n&255]; };
const lum = h => { const [r,g,b] = hex2rgb(h).map(v => { v/=255; return v <= .03928 ? v/12.92 : Math.pow((v+.055)/1.055, 2.4); }); return .2126*r + .7152*g + .0722*b; };
const ratio = (a,b) => { const x = lum(a), y = lum(b); return (Math.max(x,y)+.05)/(Math.min(x,y)+.05); };
const mix = (a,b,t) => { const A = hex2rgb(a), B = hex2rgb(b); return '#' + A.map((v,i) => Math.round(v*(1-t) + B[i]*t).toString(16).padStart(2,'0')).join(''); };
function applyDesign(){
  const r = document.documentElement, st = r.style;
  loadFont(D.font);
  const stack = `"${D.font}",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif`;
  st.setProperty('--f-body', stack); st.setProperty('--f-display', stack);
  st.fontSize = {s:'93.75%', m:'', l:'112.5%'}[D.size] || '';
  const R = {sharp:['2px','4px','6px','6px','6px','2px','4px'], soft:[], round:['16px','30px','36px','999px','30px','14px','18px']}[D.corners] || [];
  ['--r-s','--r-m','--r-l','--r-pill','--r-b','--r-tail','--r-seg'].forEach((k,i) => R[i] ? st.setProperty(k, R[i]) : st.removeProperty(k));
  r.classList.toggle('hc', D.contrast === 'high');
  const SP = ['.25rem','.5rem','.75rem','1rem','1.5rem','2rem','3rem'];
  SP.forEach((v,i) => D.density === 'compact' ? st.setProperty(`--s-${i+1}`, `calc(${v} * .8)`) : st.removeProperty(`--s-${i+1}`));
  st.setProperty('--panel-w', D.panelW + 'px'); st.setProperty('--chat-w', D.chatW + 'rem');
  r.classList.toggle('panel-right', D.side === 'right');
  r.classList.toggle('hide-time', !D.showTime); r.classList.toggle('hide-thws', !D.showThws); r.classList.toggle('show-hint', !!D.showHint);
  // colours
  const c = Object.assign({}, COLOR_DEF, D.colors), css = [];
  if (D.colors.brand){
    const ink = ratio('#1A1A1A', c.brand) >= ratio('#FFFFFF', c.brand) ? '#1A1A1A' : '#FFFFFF';
    let txt = c.brand; for (let i = 0; i < 20 && ratio(txt, '#FFFFFF') < 4.5; i++) txt = mix(txt, '#000000', .1);
    css.push(`:root,:root[data-theme]{--brand:${c.brand}!important;--brand-ink:${ink}!important}`);
    css.push(`:root:not([data-theme="dark"]){--brand-text:${txt};--brand-soft:${mix(c.brand,'#FFFFFF',.86)};--focus:#1A1A1A}`);
  }
  const light = [];
  if (D.colors.paper) light.push(`--paper:${c.paper}`);
  if (D.colors.surface) light.push(`--surface:${c.surface}`);
  if (D.colors.ink) light.push(`--ink:${c.ink}`);
  if (light.length){ const decl = light.join(';'); css.push(`@media (prefers-color-scheme: light){:root:not([data-theme="dark"]){${decl}}}`, `:root[data-theme="light"]{${decl}}`, `@media not (prefers-color-scheme: dark){:root:not([data-theme]){${decl}}}`); }
  let tag = $('#customDesign'); if (!tag){ tag = document.createElement('style'); tag.id = 'customDesign'; document.head.appendChild(tag); }
  tag.textContent = css.join('\n');
  syncDesignUI(c);
}
function syncDesignUI(c){
  c = c || Object.assign({}, COLOR_DEF, D.colors);
  $('#dFont').value = D.font; $('#dFontPrev').style.fontFamily = `"${D.font}",system-ui,sans-serif`;
  $$('[data-dseg]').forEach(sg => $$('button', sg).forEach(b => b.setAttribute('aria-pressed', String(D[sg.dataset.dseg]) === b.dataset.v)));
  $('#cBrand').value = c.brand; $('#cPaper').value = c.paper; $('#cSurface').value = c.surface; $('#cInk').value = c.ink;
  const btnInk = ratio('#1A1A1A', c.brand) >= ratio('#FFFFFF', c.brand) ? '#1A1A1A' : '#FFFFFF', rb = ratio(btnInk, c.brand), rt = ratio(c.ink, c.paper);
  $('#cContrast').innerHTML = `Button text ${rb.toFixed(1)}:1 <b class="${rb>=4.5?'ok':'bad'}">${rb>=4.5?'readable':'too low'}</b>, page text ${rt.toFixed(1)}:1 <b class="${rt>=4.5?'ok':'bad'}">${rt>=4.5?'readable':'too low'}</b>`;
  $('#dExpert').checked = D.expert; $('#dExpertBox').hidden = !D.expert;
  $('#dPanelW').value = D.panelW; $('#dPanelWOut').textContent = Math.round(D.panelW/16) + ' rem';
  $('#dChatW').value = D.chatW; $('#dChatWOut').textContent = D.chatW + ' rem';
  $('#dPanelOff').checked = !!S.panelOff;
  $('#dTime').checked = D.showTime; $('#dThws').checked = D.showThws; $('#dHint').checked = D.showHint;
}
$('#dFont').innerHTML = Object.keys(FONTS).map(f => `<option>${f}</option>`).join('');
$('#dFont').addEventListener('change', e => { D.font = e.target.value; saveD(); applyDesign(); logEv('design_changed', 'font: ' + D.font); requestAnimationFrame(positionNotes); });
$$('[data-dseg]').forEach(sg => sg.addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return; D[sg.dataset.dseg] = b.dataset.v; saveD(); applyDesign(); logEv('design_changed', sg.dataset.dseg + ': ' + b.dataset.v); }));
[['cBrand','brand'],['cPaper','paper'],['cSurface','surface'],['cInk','ink']].forEach(([id,k]) => $('#'+id).addEventListener('input', e => { D.colors[k] = e.target.value; saveD(); applyDesign(); }));
