/* ---------- Scenario panel resizing ---------- */
function clampW(w){ const body = $('.ws-body'); const max = Math.min(640, (body?.clientWidth || 1200) - 420); return Math.round(Math.max(256, Math.min(max, w))); }
function setPanelW(w, save){ D.panelW = clampW(w); document.documentElement.style.setProperty('--panel-w', D.panelW + 'px'); const rz = $('.resizer'); if (rz){ rz.setAttribute('aria-valuenow', D.panelW); rz.setAttribute('aria-valuetext', Math.round(D.panelW/16) + ' rem'); } if (save){ saveD(); syncDesignUI(); } }
app.addEventListener('pointerdown', e => {
  const rz = e.target.closest('.resizer'); if (!rz) return;
  e.preventDefault(); rz.setPointerCapture(e.pointerId); rz.classList.add('drag');
  const body = $('.ws-body').getBoundingClientRect();
  const move = ev => setPanelW(D.side === 'right' ? body.right - ev.clientX : ev.clientX - body.left, false);
  const up = () => { rz.classList.remove('drag'); rz.removeEventListener('pointermove', move); rz.removeEventListener('pointerup', up); setPanelW(D.panelW, true); positionNotes(); };
  rz.addEventListener('pointermove', move); rz.addEventListener('pointerup', up);
});
app.addEventListener('keydown', e => {
  const rz = e.target.closest?.('.resizer'); if (!rz) return;
  const dir = D.side === 'right' ? -1 : 1, step = e.shiftKey ? 64 : 16;
  if (e.key === 'ArrowRight'){ e.preventDefault(); setPanelW(D.panelW + step*dir, true); }
  else if (e.key === 'ArrowLeft'){ e.preventDefault(); setPanelW(D.panelW - step*dir, true); }
  else if (e.key === 'Home'){ e.preventDefault(); setPanelW(256, true); }
  else if (e.key === 'End'){ e.preventDefault(); setPanelW(640, true); }
});

